function outcome = getOutcome(obj)

% get choice on previous trial

outcome = cell(numel(obj),1);

for sessix = 1:numel(obj)
    outcome{sessix} = obj(sessix).bp.hit; 
    ignore = logical(obj(sessix).bp.no);
    outcome{sessix}(ignore) = nan;
end


endfunction firstLT = firstLickTime(obj)

% get time of first lickport contact, relative to go cue, on each trial

firstLT = cell(numel(obj),1);

for sessix = 1:numel(obj)
    for trix = 1:obj(sessix).bp.Ntrials
        gc = obj(sessix).bp.ev.goCue(trix);

        lickR = obj(sessix).bp.ev.lickR{trix};
        lickL = obj(sessix).bp.ev.lickL{trix};
        licktimes = sort([lickR lickL]) - gc;
        licktimes(licktimes <= 0) = []; % only keep licks that occurred after go cue

        if ~isempty(licktimes)
            firstLT{sessix}(trix) = licktimes(1);
        else
            firstLT{sessix}(trix) = nan; % no licks on this trial
        end
    end

end

if numel(firstLT) == 1
    firstLT = firstLT{1}; % just return an array rather than a cell if one session
end


endfunction prevchoice = getPrevChoice(obj)

% get choice on previous trial

prevchoice = cell(numel(obj),1);

for sessix = 1:numel(obj)
    prevchoice{sessix} = nan;

    choice = double((obj(sessix).bp.R&obj(sessix).bp.hit) | (obj(sessix).bp.L&obj(sessix).bp.miss));

    ignore = logical(obj(sessix).bp.no);

    choice(ignore) = nan;

    prevchoice{sessix} = [prevchoice{sessix} ; choice(1:end-1)];

end


end

